/**
 * PostgreSQL exporter.
 *
 * The generated file can be piped straight into psql:
 *
 *     psql -d mydb -f seed.sql
 *
 * It contains, in this order:
 *   1. CREATE TABLE IF NOT EXISTS for every table (parents first)
 *   2. the foreign key constraints, added afterwards so that the order of the
 *      CREATE TABLE statements does not matter (and so that re-running the
 *      script does not fail on an existing constraint)
 *   3. one INSERT per row
 *
 * Foreign key columns always carry a value that was really generated for the
 * referenced table, so the script satisfies its own constraints.
 */

import { sqlIdent, sqlLiteral, sqlType } from './common.js';
import type { ExportFile } from './common.js';
import type { GeneratedData } from './dataset.js';
import type { RelationalModel } from '../model.js';
import type { Schema, TableInfo } from '../types.js';

export function exportSql(data: GeneratedData): ExportFile[] {
  const model = data.model;
  const order = insertionOrder(model);
  const lines: string[] = [];

  lines.push('-- Generated by schema-seed.');
  lines.push('-- seed: ' + data.seed);
  lines.push('-- rows per table: ' + data.count);
  lines.push('-- Foreign key values are taken from the rows of the referenced table.');
  lines.push('');
  lines.push('BEGIN;');
  lines.push('');

  for (const name of order) {
    const table = model.tables.get(name);
    if (!table) continue;
    lines.push(createTable(table, model.relationalSchemas.get(name) ?? {}));
    lines.push('');
  }

  const constraintCount = addForeignKeys(model, order, lines);
  lines.push('');

  let inserts = 0;
  for (const name of order) {
    const table = model.tables.get(name);
    if (!table) continue;
    const view = data.relational.find((candidate) => candidate.name === name);
    if (!view) continue;
    for (const row of view.rows) {
      const statement = insertStatement(table, row);
      if (!statement) continue;
      lines.push(statement);
      inserts++;
    }
    lines.push('');
  }

  if (constraintCount === 0) lines.push('-- (no foreign keys)'); 
  lines.push('COMMIT;');
  lines.push('');

  const files: ExportFile[] = [{ path: 'sql/seed.sql', content: lines.join('\n') }];
  files.push({ path: 'sql/negatives.sql', content: negativeScript(data) });
  return files;
}

/** CREATE TABLE for one table. */
function createTable(table: TableInfo, schema: Schema): string {
  const properties = (schema.properties ?? {}) as Record<string, Schema>;
  const parts: string[] = [];
  const checks: string[] = [];
  for (const column of table.columns) {
    const columnSchema = properties[column.name] ?? { type: column.type };
    const type = sqlType(columnSchema, column.type);
    let line = '  ' + sqlIdent(column.name) + ' ' + type;
    if (column.name !== table.primaryKey.property && !column.nullable) line += ' NOT NULL';
    parts.push(line);
    const expression = checkExpression(column.name, columnSchema, type);
    if (expression) {
      checks.push(
        '  CONSTRAINT ' +
          sqlIdent(table.name + '_' + column.name + '_check') +
          ' CHECK (' +
          expression +
          ')',
      );
    }
  }
  parts.push(
    '  CONSTRAINT ' +
      sqlIdent(table.name + '_pkey') +
      ' PRIMARY KEY (' +
      sqlIdent(table.primaryKey.property) +
      ')',
  );
  parts.push(...checks);
  return (
    'CREATE TABLE IF NOT EXISTS ' +
    sqlIdent(table.name) +
    ' (\n' +
    parts.join(',\n') +
    '\n);'
  );
}

/** True for the SQL types that carry text. */
function isTextType(type: string): boolean {
  const upper = type.toUpperCase();
  return (
    upper.startsWith('TEXT') ||
    upper.startsWith('VARCHAR') ||
    upper.startsWith('CHAR')
  );
}

/** True for the SQL types that carry numbers. */
function isNumericType(type: string): boolean {
  const upper = type.toUpperCase();
  return [
    'INTEGER',
    'INT',
    'NUMERIC',
    'DECIMAL',
    'REAL',
    'DOUBLE',
    'BIGINT',
    'SMALLINT',
    'FLOAT',
  ].some((prefix) => upper.startsWith(prefix));
}

/**
 * The CHECK expression for one column, or null when the column has none.
 *
 * A constraint is only emitted when it matches the SQL type of the column:
 * enum / length / pattern need text, minimum / maximum need a number.
 * Anything else is skipped instead of being cast, so the DDL stays legal.
 */
function checkExpression(
  columnName: string,
  columnSchema: Schema,
  type: string,
): string | null {
  const ident = sqlIdent(columnName);
  const text = isTextType(type);
  const numeric = isNumericType(type);
  const parts: string[] = [];

  if (text && Array.isArray(columnSchema.enum) && columnSchema.enum.length > 0) {
    const values = columnSchema.enum.map((value: unknown) => sqlLiteral(value));
    parts.push(ident + ' IN (' + values.join(', ') + ')');
  }

  if (numeric && typeof columnSchema.minimum === 'number') {
    parts.push(ident + ' >= ' + String(columnSchema.minimum));
  }
  if (numeric && typeof columnSchema.maximum === 'number') {
    parts.push(ident + ' <= ' + String(columnSchema.maximum));
  }

  if (text && typeof columnSchema.minLength === 'number') {
    parts.push('char_length(' + ident + ') >= ' + String(columnSchema.minLength));
  }
  if (text && typeof columnSchema.maxLength === 'number') {
    parts.push('char_length(' + ident + ') <= ' + String(columnSchema.maxLength));
  }

  if (
    text &&
    typeof columnSchema.pattern === 'string' &&
    columnSchema.pattern.length > 0 &&
    isValidPattern(columnSchema.pattern)
  ) {
    parts.push(ident + ' ~ ' + sqlLiteral(columnSchema.pattern));
  }

  return parts.length > 0 ? parts.join(' AND ') : null;
}

/** True when the pattern is a regular expression this runtime can parse. */
function isValidPattern(pattern: string): boolean {
  try {
    new RegExp(pattern);
    return true;
  } catch {
    return false;
  }
}

/** Add the foreign key constraints once every table exists. */
function addForeignKeys(
  model: RelationalModel,
  order: string[],
  lines: string[],
): number {
  let count = 0;
  for (const name of order) {
    const table = model.tables.get(name);
    if (!table) continue;
    for (const fk of table.foreignKeys) {
      const constraint = table.name + '_' + fk.property + '_fkey';
      lines.push('DO $schema_seed$');
      lines.push('BEGIN');
      lines.push(
        '  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = ' +
          sqlLiteral(constraint) +
          ') THEN',
      );
      lines.push(
        '    ALTER TABLE ' +
          sqlIdent(table.name) +
          ' ADD CONSTRAINT ' +
          sqlIdent(constraint) +
          ' FOREIGN KEY (' +
          sqlIdent(fk.property) +
          ') REFERENCES ' +
          sqlIdent(fk.target) +
          ' (' +
          sqlIdent(fk.targetProperty) +
          ');',
      );
      lines.push('  END IF;');
      lines.push('END');
      lines.push('$schema_seed$;');
      lines.push('');
      count++;
    }
  }
  return count;
}

/** One INSERT statement. */
function insertStatement(table: TableInfo, row: Record<string, unknown>): string | null {
  const columns = table.columns
    .map((column) => column.name)
    .filter((name) => name in row);
  if (columns.length === 0) return null;
  const values = columns.map((name) => sqlLiteral(row[name]));
  return (
    'INSERT INTO ' +
    sqlIdent(table.name) +
    ' (' +
    columns.map(sqlIdent).join(', ') +
    ')\n' +
    '  VALUES (' +
    values.join(', ') +
    ')\n' +
    '  ON CONFLICT DO NOTHING;'
  );
}

/** The order the rows are inserted in: parents before children. */
export function insertionOrder(model: RelationalModel): string[] {
  const done = new Set<string>();
  const order: string[] = [];
  const visit = (name: string, stack: Set<string>): void => {
    if (done.has(name) || stack.has(name)) return;
    stack.add(name);
    const table = model.tables.get(name);
    if (table) {
      for (const fk of table.foreignKeys) visit(fk.target, stack);
    }
    stack.delete(name);
    if (!done.has(name)) {
      done.add(name);
      order.push(name);
    }
  };
  for (const name of model.order) visit(name, new Set<string>());
  return order;
}

/**
 * The negative cases as SQL.
 *
 * Every statement violates the schema on purpose; they are commented out so
 * that the file stays executable. Uncomment one to watch PostgreSQL reject it.
 */
function negativeScript(data: GeneratedData): string {
  const lines: string[] = [];
  lines.push('-- Negative cases generated by schema-seed.');
  lines.push('-- Every statement below breaks the schema on purpose.');
  lines.push('-- Uncomment one to watch PostgreSQL refuse the row.');
  lines.push('');
  const negatives = data.mode === 'relational' ? data.relationalNegatives : data.negatives;
  for (const negative of negatives) {
    const table = data.model.tables.get(negative.table);
    if (!table) continue;
    const columns = table.columns
      .map((column) => column.name)
      .filter((name) => name in negative.data);
    if (columns.length === 0) continue;
    const values = columns.map((name) => sqlLiteral(negative.data[name]));
    lines.push(
      '-- ' +
        negative.table +
        ': ' +
        negative.kind +
        ' (' +
        (negative.property ?? '') +
        ') — ' +
        negative.reason,
    );
    lines.push(
      '-- INSERT INTO ' +
        sqlIdent(negative.table) +
        ' (' +
        columns.map(sqlIdent).join(', ') +
        ')\n--   VALUES (' +
        values.join(', ') +
        ');',
    );
    lines.push('');
  }
  return lines.join('\n');
}
